// code generated by GPT4o
// 高亮并提取被搜索的关键词
export default function highlightAndTruncate(text: string, keywords: string[], contextBuffer = 20, max = 5) {
  // Highlight keywords
  keywords.forEach(keyword => {
    const regex = new RegExp(`(${keyword})`, 'gi')
    text = text.replace(regex, '<mark>$1</mark>')
  })

  // Find all occurrences of keywords with their indices
  let keywordPositions: {
    keyword: string
    index: number
  }[] = []
  keywords.forEach(keyword => {
    const regex = new RegExp(`<mark>${keyword}</mark>`, 'gi')
    let match
    while ((match = regex.exec(text)) !== null) {
      keywordPositions.push({
        keyword,
        index: match.index
      })
    }
  })

  if (keywordPositions.length === 0) {
    // No keywords found, return truncated text
    return text.length > contextBuffer ? text.substring(0, contextBuffer) + '...' : text
  }

  // Sort keyword positions by index
  keywordPositions.sort((a, b) => a.index - b.index)

  // Extract context segments around each keyword
  let segments = []
  keywordPositions.forEach(({ keyword, index }) => {
    let start = Math.max(index - contextBuffer, 0)
    let end = Math.min(index + keyword.length + contextBuffer + 13, text.length) // Adjust for <mark> tags
    segments.push({
      segment: text.substring(start, end),
      start,
      end
    })
  })

  // Merge overlapping segments and prioritize the one with most keywords
  let mergedSegments = []
  let currentSegment = segments[0]
  let currentKeywords = new Set(currentSegment.segment.match(/<mark>(.*?)<\/mark>/g) || [])

  for (let i = 1; i < segments.length; i++) {
    let segment = segments[i]
    let segmentKeywords = new Set(segment.segment.match(/<mark>(.*?)<\/mark>/g) || [])
    if (segment.start <= currentSegment.end) {
      // Overlapping segment, merge it
      currentSegment.end = Math.max(currentSegment.end, segment.end)
      currentSegment.segment = text.substring(currentSegment.start, currentSegment.end)
      currentKeywords = new Set([...currentKeywords, ...segmentKeywords])
    } else {
      // Non-overlapping, push previous segment and start a new one
      mergedSegments.push({
        segment: currentSegment.segment,
        keywords: currentKeywords,
        start: currentSegment.start,
        end: currentSegment.end
      })
      currentSegment = segment
      currentKeywords = segmentKeywords
    }
  }
  // Push the last segment
  mergedSegments.push({ segment: currentSegment.segment, keywords: currentKeywords, start: currentSegment.start, end: currentSegment.end })

  // Sort segments by number of keywords in descending order
  mergedSegments.sort((a, b) => b.keywords.size - a.keywords.size)
  if (max) {
    mergedSegments = mergedSegments.slice(0, max)
  }
  // Combine segments with ellipses
  let result = mergedSegments
    .map((seg, index) => {
      let prefix = index === 0 && seg.start > 0 ? '...' : ''
      let suffix = index === mergedSegments.length - 1 && seg.end < text.length ? '...' : ''
      return prefix + seg.segment + suffix
    })
    .join('...')

  return result
}
